int amdgpu_ib_pool_init ( struct amdgpu_device * adev ) { int r ; r = amdgpu_sa_bo_manager_init ( adev , & adev -> ring_tmp_bo , AMDGPU_IB_POOL_SIZE * 64 * 1024 , AMDGPU_GPU_PAGE_SIZE , AMDGPU_GEM_DOMAIN_GTT ) ; if ( r ) { return r ; } r = amdgpu_sa_bo_manager_start ( adev , & adev -> ring_tmp_bo ) ; if ( r ) { return r ; } adev -> ib_pool_ready = true ; if ( amdgpu_debugfs_sa_init ( adev ) ) { dev_err ( adev -> dev , "failed to register debugfs file for SA\n" ) ; } return 0 ; } 